window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"mOjgtgEXSmw","speaker":"Andy Burnham","role":"Prime Minister","country":"United Kingdom","region":"Europe","url":"https://www.youtube.com/watch?v=mOjgtgEXSmw","date":"20260923","title":"🇬🇧 United Kingdom - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1284,"words":3024,"counts":{"claims":36,"promises":28,"attacks":4},"topics":[{"topic":"United Kingdom economy","share":0.2058,"seconds":264},{"topic":"Russian disinformation","share":0.1703,"seconds":219},{"topic":"Russia Ukraine","share":0.1573,"seconds":202},{"topic":"UK AI policy","share":0.1555,"seconds":200},{"topic":"UK defense","share":0.1034,"seconds":133},{"topic":"Israel-Gaza","share":0.0985,"seconds":126},{"topic":"Climate change","share":0.0569,"seconds":73},{"topic":"Election security","share":0.0523,"seconds":67}],"timeline":[[2,66,"United Kingdom economy"],[69,137,"United Kingdom economy"],[138,201,"UK defense"],[203,280,"Russian disinformation"],[281,347,"Russian disinformation"],[348,425,"Russian disinformation"],[426,493,"Election security"],[494,567,"Climate change"],[569,638,"UK AI policy"],[640,710,"UK defense"],[711,772,"UK AI policy"],[773,842,"UK AI policy"],[843,913,"United Kingdom economy"],[914,978,"Russia Ukraine"],[978,1051,"Russia Ukraine"],[1052,1117,"Russia Ukraine"],[1118,1182,"Israel-Gaza"],[1184,1246,"Israel-Gaza"],[1247,1309,"United Kingdom economy"],[1310,1342,null]],"stances":{"United Kingdom economy":"Andy Burnham states that Britain has experienced disruption from Brexit and now possesses a unique perspective to share.","UK defense":"Andy Burnham states that the UK will continue to invest in defense, meet NATO commitments, and build hard power while avoiding escalation with Russia.","Russian disinformation":"Andy Burnham states that hostile actors, specifically Russian agencies, have conducted industrial-scale assaults on the UK's information environment by spreading lies and interfering in elections.","Election security":"Andy Burnham states that the UK will share its experience in protecting elections from interference to help other countries and enhance collective security.","Climate change":"Andy Burnham states that the climate crisis is a national security threat and asserts that Britain will continue to lead efforts to fight it alongside others.","UK AI policy":"Andy Burnham states that the UK has a unique position as an honest broker to help drive forward frontier AI and will step into that role.","Russia Ukraine":"Andy Burnham expresses strong support for Ukraine, praising the Ukrainian people's resilience and courage while stating that the British people are united behind them.","Israel-Gaza":"Andy Burnham condemns the October 7 attacks and Hamas while criticizing the Israeli government's actions in Gaza and West Bank, calling for increased aid and a two-state solution."},"claims":[{"t":54,"quote":"It is now 10 years since Brexit. My country has lived through the disruption it brought","topic":"United Kingdom economy","kind":"fact"},{"t":69,"quote":"Britain is back. We are restoring our stability, building a more dynamic economy","topic":"United Kingdom economy","kind":"fact"},{"t":111,"quote":"We need to do more to help people with the everyday cost of living","topic":"United Kingdom economy","kind":"fact"},{"t":149,"quote":"meeting our NATO commitments and strengthening European","topic":"UK defense","kind":"fact"},{"t":189,"quote":"But the last 10 years tells us that it is also about something deeper as well.","topic":"UK defense","kind":"fact"},{"t":248,"quote":"They've used bots and fake websites, falsified newspaper articles, forged the branding of 28 British organizations, including universities and the BBC.","topic":"Russian disinformation","kind":"number"},{"t":289,"quote":"The Kremlin spends around 1.3 billion pounds each year on manipulating information.","topic":"Russian disinformation","kind":"number"},{"t":323,"quote":"Over the last decade, we have given too much ground to those who want to run a negative, corrosive narrative about life in Britain, which bears no resemblance to reality.","topic":"Russian disinformation","kind":"fact"},{"t":358,"quote":"If you're struggling with the cost of living and your life is not improving or if you're a young person not in employment, education or training, you are going to be much more vulnerable to this kind of influence.","topic":"Russian disinformation","kind":"fact"},{"t":376,"quote":"When inequalities grow too wide, our societies are at greater risk.","topic":"Russian disinformation","kind":"fact"},{"t":437,"quote":"We have already supported Muldo to protect its elections from Russian interference.","topic":"Election security","kind":"fact"},{"t":488,"quote":"the eradication of smallpox or the universal declaration of human rights","topic":"Election security","kind":"fact"},{"t":494,"quote":"That is the kind of promise and hope that led Britain to host the very first meeting of this general assembly in London","topic":"Climate change","kind":"fact"},{"t":534,"quote":"The climate crisis is now a national security threat for countries around the world as this summer of extreme heat, wildfires, and floods has proved beyond doubt.","topic":"Climate change","kind":"fact"},{"t":627,"quote":"It is already speeding up cancer diagnosis in the UK, but AI has the potential to go further, not just to help prevent and treat cancer, but to help cure it.","topic":"UK AI policy","kind":"fact"},{"t":640,"quote":"AI will also be the key to economic growth, the route to transforming education, and it will be a vital tool to keep us safe.","topic":"UK defense","kind":"fact"},{"t":704,"quote":"There is a lesson from the first industrial revolution which started in northern England two centuries ago.","topic":"UK defense","kind":"fact"},{"t":731,"quote":"The UK has some of the best tech and AI talent anywhere in the world.","topic":"UK AI policy","kind":"fact"},{"t":739,"quote":"we have our worldleading AI security institute working handin glove with the US and the leading labs on AI safety.","topic":"UK AI policy","kind":"fact"},{"t":773,"quote":"We moved quickly in the G20 and smaller groups to deliver an urgent practical response. We came together to agree principles which everyone implemented at home in a way that was right for them and it worked.","topic":"UK AI policy","kind":"fact"},{"t":812,"quote":"This will bring together welcome initiatives from others like that proposed by Norway this week.","topic":"UK AI policy","kind":"fact"},{"t":863,"quote":"I am working to rebalance power across all regions of the UK. And as part of that, I have set up a second Downing Street office in Manchester.","topic":"United Kingdom economy","kind":"self_credit"},{"t":875,"quote":"Outside that office stands a statue of Abraham Lincoln. It marks the personal connection he made with Manchester and the bond between our two nations.","topic":"United Kingdom economy","kind":"fact"},{"t":902,"quote":"During the American Civil War in despite the hardships it brought them, they refused to touch raw cotton that had been picked by slaves.","topic":"United Kingdom economy","kind":"fact"},{"t":914,"quote":"In 1862, people with little power used it to help those with none on the other side of the","topic":"Russia Ukraine","kind":"fact"},{"t":970,"quote":"I was in Kev last month and it gave me a glimpse of life under Russian attack.","topic":"Russia Ukraine","kind":"fact"},{"t":978,"quote":"The traders singing the praises of their products, pushing into my hands peaches and plums from Odessa. but their stalls were out on the street because the market hall had been destroyed.","topic":"Russia Ukraine","kind":"fact"},{"t":1011,"quote":"People told me about the freezing conditions in the stations last winter when temperatures dropped below minus20 degrees outside.","topic":"Russia Ukraine","kind":"number"},{"t":1019,"quote":"Meanwhile, Russia was targeting their energy infrastructure, trying to make them suffer even more.","topic":"Russia Ukraine","kind":"fact"},{"t":1059,"quote":"strikes on civilian infrastructure are explicitly forbidden forbidden by international law","topic":"Russia Ukraine","kind":"fact"},{"t":1072,"quote":"perpetrated yet again by a permanent member of the Security Council","topic":"Russia Ukraine","kind":"fact"},{"t":1121,"quote":"Just eight weeks into becoming prime minister, working with my foreign secretary, Ed Miband, I comprehensively reset our position and we built an international coalition of countries to come with us.","topic":"Israel-Gaza","kind":"self_credit"},{"t":1134,"quote":"The terrorist attack on Israel on the 7th of October 2023 was utterly horrific.","topic":"Israel-Gaza","kind":"fact"},{"t":1184,"quote":"Last month, Israel issued tenders for the construction of the E1 mega settlement, which would drive a wedge through the West Bank and threaten to put a viable Palestinian state beyond reach.","topic":"Israel-Gaza","kind":"fact"},{"t":1197,"quote":"So, we have acted by banning trade and goods with illegal settlements, recognizing that the Israeli occupation of the Palestinian territory is unlawful and sanctioning those taking part in the construction of illegal settlements.","topic":"Israel-Gaza","kind":"self_credit"},{"t":1290,"quote":"just as those Manchester cotton workers did in the 19th century and the country did in the fight against fascism in the 20th","topic":"United Kingdom economy","kind":"fact"}],"promises":[{"t":43,"quote":"I am here today to tell you how Britain will deliver leadership in a changing world for the decade that lies ahead","topic":"United Kingdom economy","kind":"promise"},{"t":145,"quote":"So we will keep investing in our defense.","topic":"UK defense","kind":"promise"},{"t":155,"quote":"We will be relentless in building up our hard power and deterrence.","topic":"UK defense","kind":"promise"},{"t":335,"quote":"We are going to face the new decade in a different way with our eyes wide open.","topic":"Russian disinformation","kind":"promise"},{"t":342,"quote":"We are going to be much prder in standing up for our values and the rule of law.","topic":"Russian disinformation","kind":"promise"},{"t":382,"quote":"we will work to make life more affordable for people.","topic":"Russian disinformation","kind":"promise"},{"t":386,"quote":"That will be at the heart of a new 10-year plan for Britain that we will bring forward later in the year.","topic":"Russian disinformation","kind":"promise"},{"t":401,"quote":"Today I am asking our security chiefs in the UK to begin work on a new national center for information defense to detect, attribute and disrupt these kinds of hostile state information attacks to support and defend our","topic":"Russian disinformation","kind":"promise"},{"t":426,"quote":"So we are going to use our experience in the UK and the fact that we have already been through this shock starting 10 years ago to help other countries.","topic":"Election security","kind":"promise"},{"t":450,"quote":"So, we're ready to share our understanding of how these actors work and how we can respond","topic":"Election security","kind":"promise"},{"t":546,"quote":"Britain will continue to lead with others to fight this threat, to protect our children and grandchildren, to protect the natural world, and also to seize the benefits for jobs growth and that the clean energy transition can","topic":"Climate change","kind":"promise"},{"t":611,"quote":"We are going to step into that role and we are going to start with one of the most significant challenges and opportunities of our age. Frontier AI.","topic":"UK AI policy","kind":"promise"},{"t":651,"quote":"I am announcing today that we are developing a new AI defense partnership with the United States to protect our critical national infrastructure.","topic":"UK defense","kind":"promise"},{"t":759,"quote":"I am going to put AI at the heart of the UK's G20 presidency next year.","topic":"UK AI policy","kind":"promise"},{"t":791,"quote":"So we will bring the right people together on the key issues delivering on the potential of AI for good and dealing with the risks and we will work towards agreeing a single set of global principles and standards to ensure the transparency and access we need to increase our preparedness and to ensure that AI development is safe.","topic":"UK AI policy","kind":"promise"},{"t":832,"quote":"And I want to reassure the British people that ultimately we will do whatever is necessary to protect them, including bringing forward new laws if that is what is needed.","topic":"UK AI policy","kind":"promise"},{"t":843,"quote":"They need to know that we will protect their interests and we will.","topic":"United Kingdom economy","kind":"promise"},{"t":951,"quote":"We will always stand for the underdog against the bully.","topic":"Russia Ukraine","kind":"promise"},{"t":1027,"quote":"So, we're working to help Ukraine protect their skies and civilians.","topic":"Russia Ukraine","kind":"promise"},{"t":1032,"quote":"We're leading the charge in raising the cost for Russia of continuing this senseless and illegal war.","topic":"Russia Ukraine","kind":"promise"},{"t":1045,"quote":"and we will support Ukraine to repair and protect the heat and power plants that Keev will depend upon this winter.","topic":"Russia Ukraine","kind":"promise"},{"t":1087,"quote":"we will stand with Ukraine, stronger than ever, for as long as it takes","topic":"Russia Ukraine","kind":"promise"},{"t":1095,"quote":"We will stand firm in the face of any threats and challenges to the rule of law","topic":"Russia Ukraine","kind":"promise"},{"t":1172,"quote":"We will not stand by as the horrific suffering continues to grow and the prospect of a two-state solution.","topic":"Israel-Gaza","kind":"promise"},{"t":1221,"quote":"And we will do all we can to keep the hope of that alive.","topic":"Israel-Gaza","kind":"promise"},{"t":1274,"quote":"Count on us to stand up for those longstanding British values of fairness and justice, our shared values, and for the UN charter.","topic":"United Kingdom economy","kind":"promise"},{"t":1284,"quote":"Count on us to fight racism, discrimination, and the abuse of power wherever we see it","topic":"United Kingdom economy","kind":"promise"},{"t":1300,"quote":"Count on us to bring people together, not to point towards old problems, but to work towards new solutions for the 21st century.","topic":"United Kingdom economy","kind":"promise"}],"attacks":[{"t":240,"quote":"Russian agencies have used every means at their disposal to spread lies and and prey on people's fears.","topic":"Russian disinformation","target":"Russia"},{"t":281,"quote":"The idea that anyone would try to use such things to their advantage is just repulsive, but it is what they do.","topic":"Russian disinformation","target":"Russia"},{"t":296,"quote":"We're talking about an insidious campaign that reaches into people's homes and twists what they feel about their own country and community, creating a narrative of decline, stoking division and sewing despair.","topic":"Russian disinformation","target":"Russia"},{"t":1055,"quote":"we should call Russia out this time and every time","topic":"Russia Ukraine","target":"Russia"}],"greece":[],"said":[{"topic":"United Kingdom economy","said":0.2058,"reported":1.0,"articles":1},{"topic":"Russian disinformation","said":0.1703,"reported":0.0,"articles":0},{"topic":"Russia Ukraine","said":0.1573,"reported":0.0,"articles":0},{"topic":"UK AI policy","said":0.1555,"reported":0.0,"articles":0},{"topic":"UK defense","said":0.1034,"reported":0.0,"articles":0},{"topic":"Israel-Gaza","said":0.0985,"reported":0.0,"articles":0},{"topic":"Climate change","said":0.0569,"reported":0.0,"articles":0},{"topic":"Election security","said":0.0523,"reported":0.0,"articles":0}],"pickup":[{"outlet":"To Vima","date":"2026-09-22","title":"Βρετανία – ΕΕ: Ο Μπέρναμ επιχειρεί νέα προσέγγιση μέσω της αυτοκινητοβιομηχανίας","url":"https://www.tovima.gr/2026/09/22/world/vretania-ee-o-mpernam-epixeirei-nea-proseggisi-meso-tis-aytokinitoviomixanias","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-22","title":"Ο Μπέρναμ αφήνει ανοιχτό το ενδεχόμενο επιστροφής της Βρετανίας στην ΕΕ -Τι δήλωσε","url":"https://www.iefimerida.gr/kosmos/o-mpernam-den-apokleiei-epistrofi-bretanias-ee","tone":"neutral"}],"transcript":[{"t":2,"topic":"United Kingdom economy","text":"The assembly will hear an address by His Excellency Andy Bernham, Prime Minister and First Lord of the Treasury of the United Kingdom of Great Britain and Northern Ireland. I request protocol to escort his excellency and invite him to address the assembly. Madame President, your excellencies, ladies and gentlemen, as the new British Prime Minister, I am here today to tell you how Britain will deliver leadership in a changing world for the decade that lies ahead. Learning from our experience of the last one. It is now 10 years since Brexit. My country has lived through the disruption it brought and it has given us a unique perspective that I want to share with you today."},{"t":69,"topic":"United Kingdom economy","text":"Britain is back. We are restoring our stability, building a more dynamic economy, a nation that wants to trade with the world and work together to solve the shared problems we face. But we have also learned that we need to adapt to meet the challenge of these We need to rebalance power in our country and bring it closer to people. We need to work harder to fight the forces of division and instability which threaten us. Not just through hard power, but through softer, slower means that so fear and We need to do more to help people with the everyday cost of living and seize the opportunities that give them hope for the future. And we need to embrace the incredible potential of technology to improve people's lives. That's what I want to talk to you about this evening. How the world can come through the turbulence of today to reach towards something better in the decade ahead."},{"t":138,"topic":"UK defense","text":"Overcoming the forces of division and instability starts with national security. So we will keep investing in our defense. meeting our NATO commitments and strengthening European We will be relentless in building up our hard power and deterrence. But we will not play Russia's game of trading escalatory rhetoric. Unlike Russia, we do not seek confrontation. Instead, we will be prepared but not panicked, cleareyed, but cool-headed and unflinching in defending our people and our allies. True resilience depends on this military strength. But the last 10 years tells us that it is also about something deeper as well. It is about the strength of the social fabric that binds us together."},{"t":203,"topic":"Russian disinformation","text":"There is no national security without a strong cohesive society underneath it. That's the starting point for everything we hold dear and everything we want to But the fact is it has been under In recent years, we have seen industrialcale assault by hostile actors on the information environment in the UK and that of many of our allies. Russian agencies have used every means at their disposal to spread lies and and prey on people's fears. They've used bots and fake websites, falsified newspaper articles, forged the branding of 28 British organizations, including universities and the BBC. They've amplified far-right narratives, and we have evidence that they tried to interfere with the 2019 general We also know that they have tried to stoke tensions and unrest in the wake of horrific events."},{"t":281,"topic":"Russian disinformation","text":"The idea that anyone would try to use such things to their advantage is just repulsive, but it is what they do. The Kremlin spends around 1.3 billion pounds each year on manipulating information. We're talking about an insidious campaign that reaches into people's homes and twists what they feel about their own country and community, creating a narrative of decline, stoking division and sewing despair. On top of that, we have seen cyber attacks on companies and institutions, and we know that AI will multiply the We have tiptoed around this for too long. Over the last decade, we have given too much ground to those who want to run a negative, corrosive narrative about life in Britain, which bears no resemblance to reality. Well, no more. We are going to face the new decade in a different way with our eyes wide open. We are going to be much prder in standing up for our values and the rule of law."},{"t":348,"topic":"Russian disinformation","text":"And we are going to help our people to strengthen their resilience because faced with this information warfare, security starts in every home. If you're struggling with the cost of living and your life is not improving or if you're a young person not in employment, education or training, you are going to be much more vulnerable to this kind of influence. So part of the challenge is to lift our people up and create the opportunities they need. When inequalities grow too wide, our societies are at greater risk. So, we will work to make life more affordable for people. That will be at the heart of a new 10-year plan for Britain that we will bring forward later in the year. And we will put in place the architecture to stem this poisonous Today I am asking our security chiefs in the UK to begin work on a new national center for information defense to detect, attribute and disrupt these kinds of hostile state information attacks to support and defend our I know this is a shared challenge."},{"t":426,"topic":"Election security","text":"So we are going to use our experience in the UK and the fact that we have already been through this shock starting 10 years ago to help other countries. We have already supported Muldo to protect its elections from Russian interference. As more elections approach across Europe, more nations are grappling with these issues, some for the first time. So, we're ready to share our understanding of how these actors work and how we can respond because this is a vital uh task for our collective security and resilience to overcome division and instability. We must also find new ways to bring countries together. We know that we are at our strongest when we unite with others. When we reach across borders to solve shared problems. Standing here today, I am reminded of the huge human progress that this organization has led, like the eradication of smallpox or the universal declaration of human rights."},{"t":494,"topic":"Climate change","text":"That is the kind of promise and hope that led Britain to host the very first meeting of this general assembly in London and led to the world to create this institution. These United Nations, our United Nations. That is the level of ambition that we need now to renew the UN for our times to tackle challenges like improving global health and preventing future pandemics. to end the wars that are causing so much suffering and instability, including the terrible conflict in Sudan and to tackle climate change. The climate crisis is now a national security threat for countries around the world as this summer of extreme heat, wildfires, and floods has proved beyond doubt. Britain will continue to lead with others to fight this threat, to protect our children and grandchildren, to protect the natural world, and also to seize the benefits for jobs growth and that the clean energy transition can So, we must raise our sights."},{"t":569,"topic":"UK AI policy","text":"And I believe the United Kingdom has a unique position as an honest broker to help drive this forward. We are America's closest ally. We have deep ties with our friends in the European Union and seek to deepen them further. We work with China and emerging powers like India and Brazil. We sit on the UN Security Council in the Commonwealth in the CPTTP in a divided world. We have the ability to bring people together and we will. We are going to step into that role and we are going to start with one of the most significant challenges and opportunities of our age. Frontier AI. AI brings together so many of the most pressing issues before us. It is already speeding up cancer diagnosis in the UK, but AI has the potential to go further, not just to help prevent and treat cancer, but to help cure it."},{"t":640,"topic":"UK defense","text":"AI will also be the key to economic growth, the route to transforming education, and it will be a vital tool to keep us safe. I am announcing today that we are developing a new AI defense partnership with the United States to protect our critical national infrastructure. But we know that AI will also be a source of disruption to the way we live and work, a multiplier of risk. We've all heard the warnings which we must heed. I know how worried people are. So we have to rise to this moment. Fundamental decisions on this technology are too important to be left to chance. They must be taken by elected governments who serve working people. And we need to give people the support they need through this change, ensuring that it becomes an engine for re-industrialization and opportunity as There is a lesson from the first industrial revolution which started in northern England two centuries ago."},{"t":711,"topic":"UK AI policy","text":"It was a time of incredible technological But for workers, the disruption brought huge suffering and exploitation. Things got a lot worse before they got better. So this time we need to get it right. I believe we're more than equal to the The UK has some of the best tech and AI talent anywhere in the world. And when it comes to guarding against the risks, we have our worldleading AI security institute working handin glove with the US and the leading labs on AI safety. But we need to go further. Building on the meeting convened by his majesty King Charles last week, I can announce today that I am going to put AI at the heart of the UK's G20 presidency next year. I look back at how we responded to the financial crisis back in 2008."},{"t":773,"topic":"UK AI policy","text":"We moved quickly in the G20 and smaller groups to deliver an urgent practical response. We came together to agree principles which everyone implemented at home in a way that was right for them and it worked. That is the kind of approach we need now. So we will bring the right people together on the key issues delivering on the potential of AI for good and dealing with the risks and we will work towards agreeing a single set of global principles and standards to ensure the transparency and access we need to increase our preparedness and to ensure that AI development is safe. This will bring together welcome initiatives from others like that proposed by Norway this week. As his majesty said, the task before us is not merely to advance technology but to ensure that it remains firmly in the service of humanity. And I want to reassure the British people that ultimately we will do whatever is necessary to protect them, including bringing forward new laws if that is what is needed."},{"t":843,"topic":"United Kingdom economy","text":"They need to know that we will protect their interests and we will. But on its own, that's not enough, is it? In this dangerous, turbulent age, it is more important than ever that we give people the power to build their own resilience and do more for themselves and give them the platform to stand up for what they believe in. I am working to rebalance power across all regions of the UK. And as part of that, I have set up a second Downing Street office in Manchester. We call it number 10 North. Outside that office stands a statue of Abraham Lincoln. It marks the personal connection he made with Manchester and the bond between our two nations. A bond which he described in a letter to the working people of the city as perpetual. This was not due to some military or material support. There was no quid proquo. It was because Manchester's humble mill workers took a principled stand. During the American Civil War in despite the hardships it brought them, they refused to touch raw cotton that had been picked by slaves."},{"t":914,"topic":"Russia Ukraine","text":"In 1862, people with little power used it to help those with none on the other side of the The best change is change like that. Bottomup change led by people. And whatever distorted view social media offers today, the world is still full full of good and decent people all over the world who are ready to stand up for what is right. I see that shining through all the time. Nothing brings the British people together across age, race, and class more than their hatred of injustice, the misuse of power against the powerless. We will always stand for the underdog against the bully. That's why we are so united behind Ukraine. And let me say we salute the Ukrainian people. They are showing depths of resilience and courage. That is an inspiration to the whole world. I was in Kev last month and it gave me a glimpse of life under Russian attack. I went to a bustling market, just a normal scene from any European city."},{"t":978,"topic":"Russia Ukraine","text":"The traders singing the praises of their products, pushing into my hands peaches and plums from Odessa. but their stalls were out on the street because the market hall had been destroyed. In the background, there were burned out cars. Behind us, a building that had taken a direct hit just a few weeks before. I met people riding the metro home from work, people just getting on with their lives. But at night, those same metro stations, doubling as shelters for thousands of people, from the elderly to little kids, some who have known nothing but war. People told me about the freezing conditions in the stations last winter when temperatures dropped below minus20 degrees outside. Meanwhile, Russia was targeting their energy infrastructure, trying to make them suffer even more. We can't let them do that again this winter. So, we're working to help Ukraine protect their skies and civilians. We're leading the charge in raising the cost for Russia of continuing this senseless and illegal war. The Graham bill, which President Trump signed last week, will make a huge difference to that effort, and we will support Ukraine to repair and protect the heat and power plants that Keev will depend upon this winter."},{"t":1052,"topic":"Russia Ukraine","text":"It is right that we provide that support. But we should call Russia out this time and every time. Everyone in this room knows that strikes on civilian infrastructure are explicitly forbidden forbidden by international law. Yet, we stand here in the UN announcing funding to mitigate the effects of these war crimes, which we reliably expect to be perpetrated yet again by a permanent member of the Security Council. It must end. Russia could choose a different course tomorrow, accept a fe ceasefire, come to the negotiating table. I urge them to do so. But until then, we will stand with Ukraine, stronger than ever, for as long as it takes. This is about upholding the UN charter and the rule of law. We will stand firm in the face of any threats and challenges to the rule of law, not just from Russia, but from others, too, including where they threaten the rights of British territories to remain British, such as the Falkland Islands. That's why we're also working with France and other partners to support freedom of navigation in the Gulf."},{"t":1118,"topic":"Israel-Gaza","text":"And it's why I have acted on the Middle East. Just eight weeks into becoming prime minister, working with my foreign secretary, Ed Miband, I comprehensively reset our position and we built an international coalition of countries to come with us. The terrorist attack on Israel on the 7th of October 2023 was utterly horrific. I have condemned it in the strongest possible terms. We continue to condemn Hamas and we stand with Israel in the face of the ongoing threats including from Iran against Israel and Jewish people around the world. But this does not justify the Israeli government's actions in Gaza or the West Bank. Far too many people have died, including so many children. Far too little aid is getting in, and it has gone on for far too long. We will not stand by as the horrific suffering continues to grow and the prospect of a two-state solution. The best hope for peace and stability for both nations comes under attack."},{"t":1184,"topic":"Israel-Gaza","text":"Last month, Israel issued tenders for the construction of the E1 mega settlement, which would drive a wedge through the West Bank and threaten to put a viable Palestinian state beyond reach. It cannot be allowed to happen. So, we have acted by banning trade and goods with illegal settlements, recognizing that the Israeli occupation of the Palestinian territory is unlawful and sanctioning those taking part in the construction of illegal settlements. We want to see the suffering and death finally come to an end. We want to see Israeli and Palestinian people living side by side in peace and security. And we will do all we can to keep the hope of that alive. And look, we live in an age of low trust in politics. If we were to continue to talk about the two-state solution, but fail to back those words with deeds, that trust will fall even lower, and our enemies will seek to exploit the alienation that follows from that."},{"t":1247,"topic":"United Kingdom economy","text":"We won't let it happen. So, your excellencies, ladies and gentlemen, this is the kind of leadership Britain is here to bring. We need to recommmit together to make the decade ahead of us better than the last. My message to our partners around the world is this. You can count on us. Count on us to stand up for those longstanding British values of fairness and justice, our shared values, and for the UN charter. Count on us to fight racism, discrimination, and the abuse of power wherever we see it, just as those Manchester cotton workers did in the 19th century and the country did in the fight against fascism in the 20th Count on us to bring people together, not to point towards old problems, but to work towards new solutions for the 21st century."},{"t":1310,"topic":null,"text":"Count on us to meet fear and division with unity and hope. Thank you very much indeed. On behalf of the assembly, I wish to thank the prime minister and first lord of the treasury of the United Kingdom of Great Britain and Northern Ireland."}],"compare":[{"topic":"Russia-Ukraine War","share":0.3276,"mean":0.0338,"rank":6,"others":44},{"topic":"United Kingdom","share":0.1034,"mean":0.0,"rank":1,"others":0},{"topic":"Israel–Palestine","share":0.0985,"mean":0.0522,"rank":36,"others":76},{"topic":"Climate Change","share":0.0569,"mean":0.0427,"rank":57,"others":77},{"topic":"Election Security","share":0.0523,"mean":0.0003,"rank":2,"others":1}]};
